with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'البصريات الجوية والرؤية والظواهر الضوئية','انتقال الضوء في الغلاف الجوي والتشتت والانكسار والهباء والرؤية والظواهر البصرية وأجهزة القياس والتطبيقات التشغيلية.',63,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'انتقال الضوء والهباء والرؤية الجوية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الظواهر البصرية وتقنيات القياس',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('atmospheric-refractivity','انكسارية الغلاف الجوي','معامل الانكسار وتدرجه الرأسي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتغير انكسارية الهواء مع الحرارة والضغط والرطوبة، وينتج عن تدرجها انحناء مسارات الضوء والموجات الكهرومغناطيسية. تؤثر الظروف الجوية في الرصد البصري والاتصالات والاستشعار عن بعد."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"انكسارية الغلاف الجوي","text":"اشرح كيف يمكن لتدرج الحرارة أن يغير مسار شعاع ضوئي قرب السطح. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يمكن لتدرج الحرارة أن يغير مسار شعاع ضوئي قرب السطح."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8760,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('optical-scattering-atmosphere','تشتت الضوء في الغلاف الجوي','رايلي ومي وتشتت الجسيمات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يعتمد التشتت على طول موجة الإشعاع وحجم الجسيمات وخصائصها البصرية. يفسر تشتت رايلي بعض ألوان السماء، بينما يرتبط تشتت مي بالهباء والقطيرات ذات الأحجام الأكبر نسبياً."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تشتت الضوء في الغلاف الجوي","text":"قارن اعتماد تشتت رايلي ومي على الطول الموجي وحجم الجسيم. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن اعتماد تشتت رايلي ومي على الطول الموجي وحجم الجسيم."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8770,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('aerosol-optical-depth','العمق البصري للهباء','التوهين والامتصاص والتشتت','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس العمق البصري مقدار توهين الإشعاع خلال عمود جوي، ويتأثر بكمية الهباء وتوزيعه الرأسي وخصائصه البصرية. لا يحدد وحده التركيب الكيميائي أو التوزيع الرأسي للجسيمات."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"العمق البصري للهباء","text":"فسر الفرق بين قياس العمق البصري وقياس تركيز الجسيمات قرب السطح. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر الفرق بين قياس العمق البصري وقياس تركيز الجسيمات قرب السطح."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8780,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('visibility-meteorological','الرؤية الأفقية في الأرصاد','التباين والامتصاص والتشتت','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعرف الرؤية الجوية من قدرة الراصد أو الجهاز على تمييز هدف ذي تباين محدد، وتتأثر بالضباب والهباء والهطول والملوثات والإضاءة وخلفية المشهد."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الرؤية الأفقية في الأرصاد","text":"قارن العوامل التي تقلل الرؤية في الضباب والغبار والمطر. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن العوامل التي تقلل الرؤية في الضباب والغبار والمطر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8790,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('koschmieder-law','قانون كوشميدر للرؤية','معامل الانطفاء وحد التباين','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يربط قانون كوشميدر مدى الرؤية بمعامل الانطفاء البصري عند افتراضات محددة للتباين والوسط المتجانس. يجب بيان الافتراضات عند تطبيقه على بيانات حقيقية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"قانون كوشميدر للرؤية","text":"اشرح دور معامل الانطفاء في تحديد مدى الرؤية النظري. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح دور معامل الانطفاء في تحديد مدى الرؤية النظري."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8800,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('fog-droplet-optics','الخصائص البصرية لقطيرات الضباب','الحجم والتركيز والتشتت الأمامي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تؤثر أحجام قطيرات الضباب وتركيزها وتوزيعها في التشتت البصري والرؤية. وقد تختلف الرؤية عن الرطوبة النسبية وحدها بسبب اختلاف محتوى الماء السائل والخصائص الميكروفيزيائية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الخصائص البصرية لقطيرات الضباب","text":"فسر لماذا لا تكفي الرطوبة النسبية وحدها لتقدير الرؤية. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا لا تكفي الرطوبة النسبية وحدها لتقدير الرؤية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8810,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('aerosol-haze-visibility','الغبش والهباء وتأثيرهما في الرؤية','الجسيمات الدقيقة والتباين الجوي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ الغبش عندما يغير الهباء امتصاص الضوء وتشتته، فيخفض تباين الأجسام البعيدة. تختلف خصائصه بحسب الحجم والتركيب والرطوبة ومصادر الانبعاث."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الغبش والهباء وتأثيرهما في الرؤية","text":"حلل كيف تؤثر الرطوبة في الخصائص البصرية لبعض أنواع الهباء. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل كيف تؤثر الرطوبة في الخصائص البصرية لبعض أنواع الهباء."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8820,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('mirage-optical-phenomena','السراب والانكسار الطبقي','التدرج الحراري وانحناء الأشعة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينتج السراب عن تغير معامل الانكسار عبر طبقات هوائية مختلفة الحرارة، ما يؤدي إلى انحناء الأشعة وتكوين صور ظاهرية. يختلف السراب السفلي عن العلوي بحسب بنية التدرج الحراري."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"السراب والانكسار الطبقي","text":"قارن البنية الحرارية العامة المرتبطة بالسراب السفلي والعلوي. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن البنية الحرارية العامة المرتبطة بالسراب السفلي والعلوي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8830,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('atmospheric-halo-formation','الهالات الضوئية حول الشمس والقمر','انكسار الضوء في بلورات الجليد','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتج الهالات الشائعة من انكسار الضوء عبر بلورات جليدية في السحب العالية، وتتأثر بهندسة البلورات وتوزيع اتجاهاتها ومصدر الضوء."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الهالات الضوئية حول الشمس والقمر","text":"اشرح لماذا ترتبط بعض الهالات بالسحب الجليدية العالية. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا ترتبط بعض الهالات بالسحب الجليدية العالية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8840,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
('corona-and-iridescence','الإكليل وتقزح السحب','الحيود والتداخل وتوزيع القطيرات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تنتج الإكليلات وتقزحات السحب من حيود الضوء وتداخل الموجات عند مروره عبر قطرات أو عناصر مائية صغيرة ومتقاربة الحجم. تتغير الألوان والحلقات مع توزيع الأحجام وزاوية الرصد."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الإكليل وتقزح السحب","text":"ميز بين الآليات البصرية العامة للإكليل والهالة. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ميز بين الآليات البصرية العامة للإكليل والهالة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8850,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'انتقال الضوء والهباء والرؤية الجوية'),
