('atmospheric-extinction','الانطفاء الجوي للإشعاع','الامتصاص والتشتت على طول المسار','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتناقص الإشعاع المار عبر الغلاف الجوي نتيجة الامتصاص والتشتت، ويتغير الانطفاء مع الطول الموجي والكتلة الهوائية والهباء والغازات. يستخدم التصحيح الجوي لفصل أثر الغلاف عن خصائص الهدف."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"الانطفاء الجوي للإشعاع","text":"اشرح لماذا يزداد المسار البصري عادة عند انخفاض ارتفاع الشمس. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا يزداد المسار البصري عادة عند انخفاض ارتفاع الشمس."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8880,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'الظواهر البصرية وتقنيات القياس'),
('sun-photometer-measurements','قياسات مقياس ضوء الشمس','النفاذية والعمق البصري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يقيس مقياس ضوء الشمس الإشعاع المباشر عند أطوال موجية محددة، وتستخدم القياسات لاشتقاق العمق البصري للهباء بعد تصحيح الغازات والكتلة الهوائية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"يتحدد السلوك البصري للإشعاع بتفاعله مع جزيئات الهواء والغازات والهباء والقطيرات والبلورات. وتشمل العمليات الأساسية الامتصاص والتشتت والانكسار والحيود والانعكاس، ويعتمد أثرها على الطول الموجي وحجم الجسيمات والهندسة البصرية."},{"type":"heading","text":"البيانات والقياسات"},{"type":"list","items":["الطول الموجي وشدة الإشعاع وزاوية الرصد.","الرؤية ومعامل الانطفاء والعمق البصري عند توافرها.","الرطوبة والحرارة ونوع الهطول والسحب والهباء.","موقع الجهاز وارتفاعه ومعايرته وحالة نافذة القياس.","صور موثقة زمنياً ومكانياً وبيانات مرجعية للمقارنة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد العملية البصرية الأساسية المحتملة.","وثق هندسة الرصد ومصدر الضوء والظروف الجوية.","افحص خصائص الجسيمات والوسط المؤثر في الإشارة.","قارن القياس أو الصورة مع تفسير فيزيائي بديل.","اذكر حدود الاستدلال وعدم اليقين ومجال صلاحية العلاقة."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"قياسات مقياس ضوء الشمس","text":"حدد البيانات اللازمة لاشتقاق العمق البصري من قياس الإشعاع المباشر. استخدم وصفاً أو بيانات افتراضية تعليمية، وافصل بين الملاحظة البصرية وتفسير آليتها."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد البيانات اللازمة لاشتقاق العمق البصري من قياس الإشعاع المباشر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين حرارة السطح وحرارة الهواء أو بين الرؤية والرطوبة.","إهمال الطول الموجي وهندسة الإضاءة والرصد.","تفسير صورة منفردة دون وقت وموقع واتجاه.","تجاهل التوهين والتلوث ومعايرة الجهاز.","اعتبار العلاقة التقريبية صالحة خارج افتراضاتها."]},{"type":"callout","text":"تفسير الظواهر البصرية الجوية يبدأ من هندسة الرصد والخصائص الفيزيائية للوسط، ثم ينتقل إلى التصنيف والتطبيق."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تربط البصريات الجوية بين خصائص الغلاف الجوي والإشعاع المرئي ومنتجات الاستشعار عن بعد. وتتحسن موثوقية التحليل بتوثيق القياس وفهم آليته والتحقق من التفسيرات البديلة."}]}'::jsonb,8890,55,'["شرح الآلية البصرية الجوية المرتبطة بالظاهرة","تحديد القياسات والبيانات اللازمة لتفسيرها","تقييم جودة الرصد وحدود الاستنتاج البصري"]'::jsonb,'الظواهر البصرية وتقنيات القياس'),
